const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.grid}"/></svg>`;
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>{const t=document.createElement('span');t.innerHTML=icon(n.dataset.icon);const svg=t.firstChild;svg.classList.add(...n.classList);n.replaceWith(svg);});}
function safeURL(u){if(typeof u!=='string'||!u.trim())return '';try{const x=new URL(u,location.href);return ['https:','http:','blob:'].includes(x.protocol)?x.href:'';}catch{return '';}}
function img(u,alt,cls=''){const url=safeURL(u);return url?`<img src="${esc(url)}" alt="${esc(alt)}" class="${cls}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:'';}
let CATALOG=window.GAMES_CATALOG||{items:[],build:{},sources:[]};
const KEY='games.library.v1';let storageOK=true;
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');return s&&typeof s==='object'?s:{};}catch{storageOK=false;return {};}}
const defaults={hub:'',provider:'',kind:'',scope:'',hidden:false,offSteam:false,hostRating:0,q:'',collection:'',tag:'',rating:0,reviews:0,fit:0,year:'',status:'',play:'',coop:false,free:false,trailer:false,verified:false,playable:false,sort:'recommended',view:'grid',shelf:'all'};
const saved=load();let state={...defaults,...(saved.filters||{})},prefs={favorites:[],notes:{},statuses:{},ratings:{},recent:[],views:[],theme:'dark',compact:false,...saved};
for(const k of ['favorites','recent','views'])if(!Array.isArray(prefs[k]))prefs[k]=[];
for(const k of ['notes','statuses','ratings'])if(!prefs[k]||typeof prefs[k]!=='object'||Array.isArray(prefs[k]))prefs[k]={};
let games=[],byId=new Map(),filtered=[],compare=new Set(),currentGame=null,mediaIndex=0,mediaMode='trailer',hls=null,toastTimer=0,modalOrigin=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({...prefs,filters:state}));storageOK=true;}catch{storageOK=false;}}
function number(n){return Number(n||0).toLocaleString('en-US');}
function compact(n){return new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n||0);}
function recommendation(g){if(g.verification!=='verified'||g.fit==null)return null;let f=Number(g.fit);if(g.reviewCount>=30&&g.rating!=null){if(g.rating<50)f=Math.min(f,5);else if(g.rating<70)f=Math.min(f,6);else if(g.rating<80)f=Math.min(f,7);}if(!g.steamUrl)return g.confidence==='Exploratory'?Math.min(f,7):f;if(g.reviewCount<30)f=Math.min(f,7);return f;}
function tier(g){const r=recommendation(g);return r==null?'Needs verification':g.status==='Upcoming'?'On the radar':r>=9?'Start here':r>=8?'Strong pick':r>=7?'Worth exploring':'Deep cut';}
function date(g){return g.releaseDate?new Date(g.releaseDate+'T12:00:00Z').toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}):(g.releaseLabel||'Date unverified');}
function trailers(g){return (g.trailers||[]).filter(t=>t.mp4||t.webm||t.hls||t.dash||t.youtube);}
function playable(g){return g.verification==='verified'&&!g.comingSoon&&['Released','Early Access','Demo','Prototype'].includes(g.status);}
function releaseYear(g){return (g.releaseDate||'').slice(0,4)||String(g.releaseYear||'');}
function setupData(){games=CATALOG.items.map(g=>({...g,tags:g.tags||[],trailers:g.trailers||[],screenshots:g.screenshots||[]}));byId=new Map(games.map(g=>[g.id,g]));for(const g of games)g._search=[g.name,g.seedName,g.summary,g.curatorWhy,g.requirements,g.collection,...(g.hubs||[]),...(g.collections||[]),...(g.storefronts||[]).map(x=>x.provider),g.kind,g.genreScope,...g.tags,...(g.developers||[]),g.status].join(' ').toLowerCase();}
function updateURL(){try{const p=new URLSearchParams();for(const [k,v]of Object.entries(state))if(v!==defaults[k]&&v!==''&&v!==false)p.set(k,String(v));if(currentGame)p.set('game',currentGame.id);history.replaceState(null,'',location.pathname+location.search+(p.size?'#'+p.toString():''));}catch{}}
function readURL(){const p=new URLSearchParams(location.hash.slice(1));for(const k of Object.keys(defaults))if(p.has(k)){const v=p.get(k);state[k]=typeof defaults[k]==='boolean'?v==='true':typeof defaults[k]==='number'?Number(v)||0:v;}return p.get('game');}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3300);}
function setTheme(){document.body.classList.toggle('light',prefs.theme==='light');document.body.classList.toggle('compact',!!prefs.compact);}
function options(){const coll=[...new Set(games.flatMap(g=>g.collections||[g.collection]))].sort(),tags=[...new Set(games.flatMap(g=>g.tags))].sort(),years=[...new Set(games.map(releaseYear).filter(Boolean))].sort().reverse();$('#f-collection').innerHTML='<option value="">All collections</option>'+coll.map(c=>`<option>${esc(c)}</option>`).join('');$('#f-tag').innerHTML='<option value="">All genres & mechanics</option>'+tags.map(c=>`<option>${esc(c)}</option>`).join('');$('#f-year').innerHTML='<option value="">All years</option>'+years.map(y=>`<option>${y}</option>`).join('');$('#collections').innerHTML=coll.map(c=>`<button class="nav-item collection-link" data-collection="${esc(c)}"><span class="collection-dot"></span>${esc(c)}<b>${games.filter(g=>(g.collections||[g.collection]).includes(c)).length}</b></button>`).join('');$('#stat-games').textContent=games.length;$('#nav-total').textContent=games.length;$('#stat-collections').textContent=coll.length;$('#stat-trailers').textContent=games.filter(g=>trailers(g).length).length;$('#last-sync').textContent=CATALOG.generatedAt?'Source snapshot: '+new Date(CATALOG.generatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No verified snapshot loaded';extraOptions();renderViews();}
function syncControls(){$('#search').value=state.q;$('#sort').value=state.sort;for(const k of ['hub','provider','kind','scope','hostRating','collection','tag','rating','reviews','fit','year','status','play'])$('#f-'+k).value=String(state[k]);for(const k of ['coop','free','trailer','verified','playable','hidden','offSteam'])$('#f-'+k).checked=!!state[k];$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view));});$$('[data-shelf]').forEach(b=>b.classList.toggle('active',b.dataset.shelf===state.shelf));$$('[data-collection]').forEach(b=>b.classList.toggle('active',b.dataset.collection===state.collection));}
function queryMatches(g,q){const tokens=q.match(/(?:[^\s"]+|"[^"]*")+/g)||[];return tokens.every(raw=>{const term=raw.replace(/"/g,'').toLowerCase(),m=term.match(/^(score|rating|reviews|year)(>=|<=|>|<|=)(\d+(?:\.\d+)?)$/);if(m){const a=m[1]==='score'?recommendation(g):m[1]==='rating'?g.rating:m[1]==='reviews'?g.reviewCount:Number(releaseYear(g));if(a==null)return false;const b=+m[3];return {'>=':a>=b,'<=':a<=b,'>':a>b,'<':a<b,'=':a===b}[m[2]];}const c=term.match(/^(tag|genre|developer|status|year|collection|hub|provider|kind):(.*)$/);if(c){const fields={tag:g.tags,genre:[...(g.genres||[]),...g.tags],developer:g.developers||[],status:[g.status],year:[releaseYear(g)],collection:g.collections||[g.collection],hub:g.hubs||['Roguelites'],provider:(g.storefronts||[]).map(x=>x.provider),kind:[g.kind||'Standalone game']};return fields[c[1]].some(x=>x.toLowerCase().includes(c[2]));}if(term.startsWith('-')&&term.length>1)return !g._search.includes(term.slice(1));return (g._search+' '+String(prefs.notes[g.id]||'').toLowerCase()).includes(term);});}
function filterGames(){filtered=games.filter(g=>{if(state.shelf==='favorites'&&!prefs.favorites.includes(g.id))return false;if(state.shelf==='backlog'&&prefs.statuses[g.id]!=='Backlog')return false;if(state.shelf==='recent'&&!prefs.recent.includes(g.id))return false;if(state.hub&&!(g.hubs||['Roguelites']).includes(state.hub))return false;if(state.provider&&!(g.storefronts||[]).some(x=>x.provider===state.provider))return false;if(state.kind&&g.kind!==state.kind)return false;if(state.scope&&g.genreScope!==state.scope)return false;if(state.hidden&&!hiddenGem(g))return false;if(state.offSteam&&!(g.storefronts||[]).some(x=>x.provider!=='Steam'&&x.kind!=='support'))return false;if(state.collection&&!(g.collections||[g.collection]).includes(state.collection))return false;if(state.tag&&!g.tags.includes(state.tag))return false;if(state.hostRating&&(!g.externalRating||100*g.externalRating.value/g.externalRating.max<state.hostRating))return false;if(state.rating&&(g.rating==null||g.rating<state.rating))return false;if(state.reviews&&(g.reviewCount||0)<state.reviews)return false;if(state.fit&&(recommendation(g)==null||recommendation(g)<state.fit))return false;if(state.year&&releaseYear(g)!==state.year)return false;if(state.status&&g.status!==state.status)return false;if(state.play&&prefs.statuses[g.id]!==state.play)return false;if(state.coop&&!g.tags.includes('Co-op'))return false;if(state.free&&!g.free)return false;if(state.trailer&&!trailers(g).length)return false;if(state.verified&&g.verification!=='verified')return false;if(state.playable&&!playable(g))return false;return queryMatches(g,state.q);});
const desc=(a,b,key)=>((b[key]??-Infinity)-(a[key]??-Infinity));filtered.sort((a,b)=>{let n=0;switch(state.sort){case'host':n=((b.externalRating?.value/b.externalRating?.max)||-1)-((a.externalRating?.value/a.externalRating?.max)||-1)||(b.externalRating?.count||0)-(a.externalRating?.count||0);break;case'rating':n=desc(a,b,'rating')||desc(a,b,'reviewCount');break;case'reviews':n=desc(a,b,'reviewCount');break;case'newest':n=(b.releaseDate||String(b.releaseYear||'0000')).localeCompare(a.releaseDate||String(a.releaseYear||'0000'));break;case'oldest':n=(a.releaseDate||String(a.releaseYear||'9999')).localeCompare(b.releaseDate||String(b.releaseYear||'9999'));break;case'name':n=a.name.localeCompare(b.name);break;case'price':n=(a.free?0:a.priceMinor??Infinity)-(b.free?0:b.priceMinor??Infinity);break;case'personal':n=(prefs.ratings[b.id]||0)-(prefs.ratings[a.id]||0);break;default:n=(recommendation(b)??-1)-(recommendation(a)??-1)||desc(a,b,'reviewCount');}if(state.shelf==='recent')n=prefs.recent.indexOf(a.id)-prefs.recent.indexOf(b.id);return n||a.name.localeCompare(b.name);});}
function card(g){const r=recommendation(g),fav=prefs.favorites.includes(g.id),ts=trailers(g),tags=g.tags.filter(t=>t!==g.collection&&!['Action','Indie','Early Access'].includes(t)).slice(0,3);return `<article class="game-card ${g.verification==='verified'?'':'unverified'}" data-game="${esc(g.id)}"><div style="position:relative"><button class="card-image" data-open="${esc(g.id)}" aria-label="Explore ${esc(g.name)}">${g.image?img(g.image,g.name+' official artwork'):`<span class="image-fallback">${esc(g.name)}<small style="font-size:10px;margin-top:8px">Artwork awaiting verification</small></span>`}</button><div class="card-topline"><span class="rec-label">${esc(tier(g))}</span><button class="save-button ${fav?'saved':''}" data-save="${esc(g.id)}" aria-label="${fav?'Unsave':'Save'} ${esc(g.name)}" aria-pressed="${fav}">${icon('heart')}</button></div>${ts.length?`<button class="play-overlay" data-trailer="${esc(g.id)}">${icon('play')} Trailer</button>`:''}</div><div class="card-body"><div class="card-collection">${esc(g.collection)}</div><button class="title-button" data-open="${esc(g.id)}"><h3 class="card-title" title="${esc(g.name)}">${esc(g.name)}</h3></button><p class="card-description">${esc(g.summary)}</p><div class="card-metrics"><div class="metric"><strong>${esc(ratingText(g))}${g.rating!=null?'<span> positive</span>':''}</strong><small>${esc(reviewText(g))}</small></div><div class="metric recommend"><strong>${r==null?'Pending':r+'<span> / 10</span>'}</strong><small>Recommendation</small></div></div><div class="card-tags">${tags.map(t=>`<button class="tag" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}${g.status==='Early Access'?'<span class="tag">Early Access</span>':''}${g.free?'<span class="tag">Free</span>':''}</div><div class="card-footer"><span class="footer-date">${esc(g.status==='Upcoming'?'Upcoming':releaseYear(g)||'Unverified')}${g.price?' &middot; '+esc(g.price):''}</span><span class="card-footer-actions"><label class="compare-check"><input type="checkbox" data-compare="${esc(g.id)}" ${compare.has(g.id)?'checked':''} aria-label="Compare ${esc(g.name)}">Compare</label><a class="steam-link" href="${esc(projectURL(g))}" target="_blank" rel="noopener" aria-label="${g.verification==='verified'?'Open':'Unverified link for'} ${esc(g.name)} on ${esc(g.provider||'official site')}">${esc(g.provider||'Official site')} ${icon('external')}</a></span></div></div></article>`;}
function table(){return `<table><thead><tr><th><button data-sort="name">Game / collection</button></th><th><button data-sort="recommended">Recommendation</button></th><th><button data-sort="rating">Community rating</button></th><th><button data-sort="reviews">Reviews</button></th><th><button data-sort="newest">Release</button></th><th>Status</th><th><button data-sort="price">Price (US)</button></th><th>Compare</th><th>Save</th><th>Store</th></tr></thead><tbody>${filtered.map(g=>`<tr><td><button class="table-name" data-open="${esc(g.id)}">${img(g.image,'')}<span><strong>${esc(g.name)}</strong><small>${esc(g.collection)}</small></span></button></td><td>${recommendation(g)??'Pending'}${recommendation(g)!=null?' / 10':''}</td><td class="rating-number">${esc(ratingText(g))}</td><td>${number(g.steamUrl?g.reviewCount:g.externalRating?.count||0)}</td><td>${esc(date(g))}</td><td>${esc(g.status)}</td><td>${g.free?'Free':esc(g.price||'Unknown')}</td><td><input type="checkbox" data-compare="${esc(g.id)}" ${compare.has(g.id)?'checked':''} aria-label="Compare ${esc(g.name)}"></td><td><button data-save="${esc(g.id)}" aria-label="Save ${esc(g.name)}" aria-pressed="${prefs.favorites.includes(g.id)}">${icon(prefs.favorites.includes(g.id)?'check':'heart')}</button></td><td><a href="${esc(projectURL(g))}" target="_blank" rel="noopener" aria-label="Open ${esc(g.name)} on ${esc(g.provider||'official site')}">${icon('external')}</a></td></tr>`).join('')}</tbody></table>`;}
function render(){filterGames();renderHub();$('#results').className=state.view==='table'?'game-table':state.view==='gallery'?'game-grid gallery-view':'game-grid';$('#results').innerHTML=filtered.length?(state.view==='table'?table():filtered.map(card).join('')):`<div class="empty"><h3>${games.length?'No games match this combination.':'The library snapshot is not loaded.'}</h3><p>${games.length?'Try fewer filters, a different search, or another collection. Your saved games are still here.':'Use the built release or run python3 scripts/build.py after refreshing Steam data.'}</p><button class="primary" data-action="reset">Reset filters</button></div>`;$('#result-count').textContent=filtered.length;const names={all:'Explore the collection',favorites:'Your saved games',backlog:'Your next adventures',recent:'Recently viewed'};$('#library-title').firstChild.textContent=(state.collection||names[state.shelf]||names.all)+' ';$('#results-caption').textContent=`${number(filtered.length)} of ${number(games.length)} games${state.sort==='rating'?'  \u00b7  Raw Steam positive percentage; review counts shown':state.sort==='host'?'  \u00b7  Native host scores, ordered by fraction of their own scale; not Steam percentages':''}`;$('#nav-saved').textContent=prefs.favorites.length;$('#nav-backlog').textContent=Object.values(prefs.statuses).filter(v=>v==='Backlog').length;renderChips();syncControls();renderCompareTray();persist();updateURL();}
function renderChips(){const labels={hub:'Genre hub',provider:'Platform',kind:'Build type',scope:'FPS style',hostRating:'Native score minimum (of max)',hidden:'Hidden gems',offSteam:'Beyond Steam',q:'Search',collection:'Collection',tag:'Genre',rating:'Steam  \u00b7  min %',reviews:'Min reviews',fit:'Recommendation',year:'Year',status:'Status',play:'Your status',coop:'Co-op',free:'Free',trailer:'Has trailer',verified:'Verified',playable:'Playable now'};const active=Object.keys(labels).filter(k=>state[k]!==defaults[k]);$('#active-filters').innerHTML=active.map(k=>`<button class="filter-chip" data-clear="${k}">${esc(labels[k])}${typeof state[k]==='boolean'?'':': '+esc(state[k])}${icon('close')}</button>`).join('')+(active.length?'<button class="tiny" data-action="reset">Clear all</button>':'');$('#filter-count').textContent=active.length;$('#filter-count').hidden=!active.length;}
function renderViews(){$('#saved-views').innerHTML=prefs.views.length?prefs.views.map((v,i)=>`<div class="saved-view"><button class="nav-item" data-load-view="${i}">${icon('bookmark')}${esc(v.name)}</button><button class="tiny" data-delete-view="${i}" aria-label="Delete saved view ${esc(v.name)}">${icon('close')}</button></div>`).join(''):'<p style="font-size:10px;color:var(--muted);padding:0 13px;line-height:1.7">Make a filter combination yours.<br>Save it for next time.</p>';}
function renderCompareTray(){$('#compare-tray').hidden=!compare.size;$('#compare-count').textContent=compare.size+' game'+(compare.size===1?'':'s')+' selected';$('#compare-mini').innerHTML=[...compare].map(id=>byId.get(id)).filter(Boolean).map(g=>img(g.image,g.name)).join('');$('#compare-tray [data-action=compare]').disabled=compare.size<2;}
function setCompare(id,on){if(on&&compare.size>=4&&!compare.has(id)){toast('Compare up to four games at a time.');$$('[data-compare]').filter(n=>n.dataset.compare===id).forEach(n=>n.checked=false);return;}on?compare.add(id):compare.delete(id);$$('[data-compare]').filter(n=>n.dataset.compare===id).forEach(n=>n.checked=compare.has(id));renderCompareTray();}
function toggleSave(id){prefs.favorites=prefs.favorites.includes(id)?prefs.favorites.filter(x=>x!==id):[...prefs.favorites,id];render();$$('[data-save]').filter(x=>x.dataset.save===id).forEach(b=>{const on=prefs.favorites.includes(id);b.classList.toggle('saved',on);b.setAttribute('aria-pressed',String(on));if(b.classList.contains('detail-save'))b.innerHTML=icon(on?'check':'heart')+(on?'Saved':'Save game');});}
function openModal(html){modalOrigin=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;icons($('#modal'));}
function stopMedia(){if(hls){hls.destroy();hls=null;}const v=$('#media-video');if(v){v.pause();v.removeAttribute('src');v.load();}}
function closeModal(){stopMedia();$('#modal').close();$('#modal-body').innerHTML='';currentGame=null;updateURL();if(modalOrigin?.isConnected)modalOrigin.focus();}
const whyNotes={'2218750':'The reference point: old-school dungeon atmosphere, horde clearing, and escalating character builds. Start here when you want the collection at its most focused.','2334730':'One of the clearest bridges between survivors-style horde combat and loot-driven dark fantasy. Prioritize it for equipment and blessing combinations.','2067920':'Prioritize this for layered runs and build experimentation rather than simply surviving a single arena timer.','2820820':'A close atmospheric match for the dark-fantasy side of the collection, with a more modern 3D presentation.','2002220':'A strong fit when you want darker fantasy and more deliberate movement rather than only passive screen clearing.','375480':'An adjacent pick, not a survivors clone. The draw here is deep loot-driven character development and clearing packs of monsters.','1104280':'An adjacent action RPG for the equipment and buildcrafting side of your taste. Expect a different structure from timed survivors runs.','2088570':'A strong choice for classes, items, and replayable dungeon runs. More manual bullet-dodging than Halls of Torment.','2665680':'High thematic relevance to your dark-fantasy and loot preferences. Judge the Steam review sample alongside this recommendation.','2286450':'A particularly relevant direction for skill-tree experimentation and horde survival in a dark-fantasy setting.','1918040':'A good fit for a straightforward fantasy bullet-heaven loop without needing the gloomy Diablo aesthetic.','2066020':'A high-priority buildcrafting pick when ability synergies and escalating power matter more than retro visuals.','2321470':'Mining and changing terrain give this horde-clearing loop a different rhythm from a conventional arena.','1942280':'A high-priority pick for compact, repeatable build experiments. Its visual tone is much lighter than the dark-fantasy collection.','2420510':'A free entry point to the broader survivors genre. Consider it for variety even though its theme is far from Halls of Torment.','1145350':'An adjacent recommendation for active combat and run-based character builds, not an automatic-attacking survivors game.','2747550':'The first-person branch of the collection. Prioritize this for a darker shooter atmosphere rather than the isometric camera.'};
function why(g){if(g.curatorWhy)return g.curatorWhy;if(g.verification!=='verified')return 'This entry is preserved, not endorsed. The earlier recommendation could not yet be reconciled with an official Steam listing. It has no recommendation score until its identity is verified.';let s=whyNotes[g.appid]||({'Dark fantasy':'A thematic match for your Halls of Torment preference. Its placement emphasizes dark-fantasy atmosphere and the kind of escalating combat builds you asked for.','Loot-driven ARPGs':'An adjacent recommendation for loot, equipment, and long-term character builds. This shelf deliberately distinguishes full action RPGs from survivors-style roguelites.','Offbeat hybrids':'A change of pace within the broader collection. Explore this when you want the familiar upgrade loop remixed with a different mechanic.','Action roguelites':'An adjacent action-focused recommendation. Expect more hands-on combat than a typical automatic-attacking survivors game.','Sci-fi & machines':'A mechanical or science-fiction alternative to the fantasy setting, chosen for horde combat and upgrade experimentation.'}[g.collection]||'A researched discovery from this genre collection. Inspect the official description, media, build status, and review sample to decide whether its style fits your taste.');if((g.steamUrl?g.reviewCount:(g.externalRating?.count||0))<100)s+=' Player evidence is still limited, so treat this as a discovery rather than a safe buy.';if(g.rating!=null&&g.rating<80&&g.reviewCount>=30)s+=' Its mixed player reception lowers the recommendation score; inspect recent reviews before buying.';if(g.status==='Upcoming')s+=' This is currently a watchlist entry, not a playable-now recommendation.';return s;}
function openGame(id,watch=false){const g=byId.get(id);if(!g)return;stopMedia();currentGame=g;mediaIndex=0;mediaMode=watch&&trailers(g).length?'trailer':trailers(g).length?'trailer':'screenshots';prefs.recent=[id,...prefs.recent.filter(x=>x!==id)].slice(0,100);persist();const r=recommendation(g),fav=prefs.favorites.includes(id);openModal(`<div class="modal-banner" style="background-image:url('${esc(safeURL(g.background||g.image))}')"><div><span class="pill">${esc(g.collection)} &nbsp; / &nbsp; ${esc(g.status)}</span><h2>${esc(g.name)}</h2><p>${esc((g.developers||[]).join('  \u00b7  ')||'Developer not verified')}</p></div></div><div class="detail-content"><div class="detail-actions"><a class="primary" href="${esc(projectURL(g))}" target="_blank" rel="noopener">${icon('external')}${esc(g.provider==='Steam'?'Open on Steam':'Open '+(g.provider||'official site'))}</a><button class="secondary detail-save ${fav?'saved':''}" data-save="${esc(id)}">${icon(fav?'check':'heart')}${fav?'Saved':'Save game'}</button><button class="secondary" data-add-compare="${esc(id)}">${icon('list')}Compare</button><button class="secondary" data-copy-game="${esc(id)}">${icon('link')}Copy game link</button><select id="detail-status" aria-label="Your play status"><option value="">Set play status</option>${['Backlog','Playing','Completed','Dropped'].map(s=>`<option ${prefs.statuses[id]===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="detail-stats"><div class="stat-box"><strong>${esc(ratingText(g))}</strong><small>${esc(reviewText(g))}</small></div><div class="stat-box"><strong>${r==null?'Pending':r+' / 10'}</strong><small>Recommendation  \u00b7  ${esc(tier(g))}</small></div><div class="stat-box"><strong style="font-size:14px">${esc(date(g))}</strong><small>Source release date</small></div><div class="stat-box"><strong>${g.free?'Free':esc(g.price||'Unknown')}</strong><small>US store snapshot${g.discount?'  \u00b7  '+g.discount+'% off':''}, not live pricing</small></div></div><section class="detail-section recommendation-note"><h3>Why it's in your collection</h3><p>${esc(why(g))}</p></section><section class="detail-section"><h3>Inside the game</h3><p>${esc(g.summary)}</p><div class="detail-tags">${g.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></section><section class="detail-section" id="media-section"><h3>See it in action</h3><div class="media-tabs"><button data-media-mode="trailer" class="${mediaMode==='trailer'?'active':''}">Official trailers (${trailers(g).length})</button><button data-media-mode="screenshots" class="${mediaMode==='screenshots'?'active':''}">Screenshots (${g.screenshots.length})</button></div><div id="media-area"></div></section>${sourcePanel(g)}<section class="detail-section"><h3>Make it yours</h3><div class="notes-area"><label>Your private notes<textarea id="game-notes" placeholder="Build ideas, reasons to play, things to check...">${esc(prefs.notes[id]||'')}</textarea></label><label>Your personal rating<select id="personal-rating"><option value="">Not played / unrated</option>${Array.from({length:10},(_,i)=>10-i).map(n=>`<option value="${n}" ${Number(prefs.ratings[id])===n?'selected':''}>${n} / 10</option>`).join('')}</select><small style="display:block;margin-top:10px;line-height:1.7">Stored in this browser. Export a backup in settings to move devices.</small></label></div></section>${(g.warnings||[]).length?`<div class="warning">${g.warnings.map(esc).join('<br>')}</div>`:''}<div class="source-line"><span>${g.verifiedAt?'Source facts checked '+esc(new Date(g.verifiedAt).toLocaleString()):'Official identity has not been verified'}</span><a href="${esc(projectURL(g))}" target="_blank" rel="noopener">Official source</a><a href="https://github.com/Herbertofury/Games/issues/new?template=game.yml&title=${encodeURIComponent('Correction: '+g.name)}" target="_blank" rel="noopener">Suggest a correction</a><span>Editorial fit is not a play-tested review.</span></div></div>`);renderMedia();updateURL();if(watch)setTimeout(()=>$('#media-section')?.scrollIntoView({block:'start',behavior:'instant'}),30);}
async function loadHls(){if(window.Hls)return window.Hls;return new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/hls.js@1.7.3/dist/hls.min.js';s.onload=()=>resolve(window.Hls);s.onerror=()=>reject(Error('Video library unavailable'));document.head.append(s);});}
async function renderMedia(){stopMedia();const g=currentGame;if(!g)return;const data=mediaMode==='trailer'?trailers(g):g.screenshots;mediaIndex=Math.min(mediaIndex,Math.max(data.length-1,0));$$('[data-media-mode]').forEach(n=>n.classList.toggle('active',n.dataset.mediaMode===mediaMode));if(!data.length){$('#media-area').innerHTML=`<div class="media-stage"><p class="media-message">${mediaMode==='trailer'?'No embeddable official trailer was supplied by the creator source.':'No verified screenshots are available for this entry.'}<br><a href="${esc(projectURL(g))}" target="_blank" rel="noopener">Open the official game page</a></p></div>`;return;}const a=data[mediaIndex];$('#media-area').innerHTML=`<div class="media-stage">${mediaMode==='trailer'?`<video id="media-video" controls playsinline preload="metadata" poster="${esc(safeURL(a.poster||g.image))}" aria-label="${esc(a.name||g.name+' official trailer')}"></video>`:img(a.src,g.name+' screenshot '+(mediaIndex+1))}</div><div class="gallery-controls"><button class="secondary" data-media-step="-1" aria-label="Previous media">Previous</button><span>${mediaIndex+1} / ${data.length}  \u00b7  ${esc(mediaMode==='trailer'?a.name||'Official trailer':'Official screenshot')}</span><button class="secondary" data-media-step="1" aria-label="Next media">Next</button></div><div class="thumbs">${data.map((m,i)=>`<button data-media-index="${i}" class="${i===mediaIndex?'active':''}" aria-label="${mediaMode==='trailer'?'Trailer':'Screenshot'} ${i+1}">${img(m.thumbnail||m.poster||m.src||g.image,'')}</button>`).join('')}</div><p style="font-size:9px;color:var(--muted);margin-top:7px">Official creator / publisher media. Trailers stream on demand; no autoplay. <a href="${esc(projectURL(g))}" target="_blank" rel="noopener" style="text-decoration:underline">Source / playback fallback</a></p>`;if(mediaMode!=='trailer')return;if(a.youtube){const stage=$('.media-stage');stage.innerHTML=`<div class="youtube-consent">${img(a.poster||g.image,g.name+' official trailer')}<button class="primary" data-youtube="${esc(a.youtube)}">${icon('play')}Play official video</button><p>Loads YouTube on click. <a href="https://www.youtube.com/watch?v=${esc(a.youtube)}" target="_blank" rel="noopener">Open video separately</a></p></div>`;return;}const v=$('#media-video'),identity=g.id;v.addEventListener('error',()=>{if(!v.isConnected)return;const note=document.createElement('p');note.className='warning';note.innerHTML=`This stream could not be played here. Try another trailer or <a href="${esc(projectURL(g))}" target="_blank" rel="noopener">watch at the official source</a>.`;v.parentElement.after(note);},{once:true});if(a.mp4||a.webm){v.src=safeURL(a.mp4||a.webm);return;}if(a.hls){if(v.canPlayType('application/vnd.apple.mpegurl')){v.src=safeURL(a.hls);return;}try{const Hls=await loadHls();if(!v.isConnected||currentGame?.id!==identity)return;if(Hls.isSupported()){hls=new Hls({enableWorker:true,maxBufferLength:30});hls.loadSource(safeURL(a.hls));hls.attachMedia(v);hls.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal&&v.isConnected)v.dispatchEvent(new Event('error'));});}else v.dispatchEvent(new Event('error'));}catch{v.dispatchEvent(new Event('error'));}}else v.dispatchEvent(new Event('error'));}
function openCompare(){const gs=[...compare].map(id=>byId.get(id)).filter(Boolean);if(gs.length<2){toast('Select at least two games to compare.');return;}stopMedia();currentGame=null;openModal(`<div class="simple-modal"><span class="eyebrow">SIDE BY SIDE</span><h2 style="margin-top:12px">Find your next game.</h2><p>Native platform reception, editorial fit, installation requirements, and your own notes.</p><div class="compare-grid" style="grid-template-columns:repeat(${gs.length},minmax(190px,1fr))">${gs.map(g=>`<article class="compare-column">${img(g.image,g.name)}<h3>${esc(g.name)}</h3>${[['Recommendation',(recommendation(g)??'Pending')+(recommendation(g)!=null?' / 10':'')],['Community reception',ratingText(g)+' / '+reviewText(g)],['Release',date(g)],['Availability',g.status],['US price snapshot',g.free?'Free':g.price||'Unknown'],['Collection',g.collection],['Co-op',g.tags.includes('Co-op')?'Listed by source':'Not verified'],['Build type',g.kind||'Standalone game'],['Requirements',g.requirements||'See official store requirements'],['Your play status',prefs.statuses[g.id]||'Not set'],['Your personal rating',prefs.ratings[g.id]?prefs.ratings[g.id]+' / 10':'Not rated'],['Your notes',prefs.notes[g.id]||'No notes yet']].map(([k,v])=>`<div class="compare-field"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}<div class="compare-field"><a class="primary" href="${esc(projectURL(g))}" target="_blank" rel="noopener">${esc(g.provider||'Official page')} ${icon('external')}</a></div></article>`).join('')}</div></div>`);updateURL();}
function featuredGame(){return games.find(g=>g.appid===(state.hub==='Boomer shooters'?3115160:2218750)&&g.verification==='verified')||games.find(g=>!state.hub||(g.hubs||[]).includes(state.hub));}
function hero(){const g=featuredGame();if(!g)return;$('#feature-art').style.backgroundImage=`url("${safeURL(g.screenshots?.[0]?.src||g.background||g.image)}")`;$('#hero-title').textContent=g.name;$('#hero-facts').innerHTML=`<span><strong>${esc(ratingText(g))}</strong> &middot; ${esc(reviewText(g))}</span><span>${esc(g.status)}</span><span>${esc(releaseYear(g))}</span>`;$('#hero-summary').textContent=state.hub==='Boomer shooters'?'Heavy weapons. Labyrinthine levels. The latest chapter in a gloriously loud rabbit hole.':'Dark dungeons. Impossible hordes. Beautifully broken builds. Your starting point for a very good rabbit hole.';}

function reset(){state={...defaults,view:state.view,sort:state.sort};render();}
function preset(name){state={...defaults,hub:state.hub,view:state.view};if(name==='torment'){if(state.hub==='Boomer shooters'){state.hidden=true;}else{state.hub='Roguelites';state.collection='Dark fantasy';}state.playable=true;}if(name==='outside'){state.offSteam=true;}if(name==='patreon'){state.provider='Patreon';}if(name==='mods'){state.kind='Mod / expansion';}if(name==='demos'){state.status='Demo';}if(name==='best'){state.fit=8;state.rating=80;state.reviews=100;state.playable=true;}if(name==='new'){state.sort='newest';state.playable=true;}render();$('#library').scrollIntoView({block:'start',behavior:'smooth'});}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function backup(){download('Games - Personal Library Backup.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),favorites:prefs.favorites,notes:prefs.notes,statuses:prefs.statuses,ratings:prefs.ratings,recent:prefs.recent,views:prefs.views,theme:prefs.theme,compact:prefs.compact,filters:state},null,2));}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportData(format){if(format==='csv'){const rows=[['Game','Collection','Recommendation /10','Steam positive %','Review count','Release','Status','Official URL','Platform','Native rating','Native scale','Native count','Build type','Requirements','Personal rating','Play status','Notes'],...filtered.map(g=>[g.name,g.collection,recommendation(g),g.rating,g.reviewCount,g.releaseDate||g.releaseLabel,g.status,projectURL(g),g.provider,g.externalRating?.value,g.externalRating?.max,g.externalRating?.count,g.kind,g.requirements,prefs.ratings[g.id],prefs.statuses[g.id],prefs.notes[g.id]])];download('Games - Filtered Collection.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}else download('Games - Filtered Collection.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),filters:state,source:CATALOG.sourceRepository,items:filtered.map(({_search,...g})=>g)},null,2));toast('Exported '+filtered.length+' games.');}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Link copied.');}catch{openModal(`<div class="simple-modal"><h2>Copy this link</h2><p>Clipboard access is not available in this browser context.</p><input type="text" value="${esc(s)}" aria-label="Link to copy" id="copy-field" readonly></div>`);$('#copy-field').select();}}
function gameLink(id){const base=location.protocol==='file:'?'https://herbertofury.github.io/Games/':location.origin+location.pathname;return base+'#game='+encodeURIComponent(id);}
function health(){stopMedia();currentGame=null;const unresolved=games.filter(g=>g.verification!=='verified'),noTrailer=games.filter(g=>g.verification==='verified'&&!trailers(g).length),stale=games.filter(g=>g.lastRefreshError);openModal(`<div class="simple-modal"><span class="eyebrow">NO MYSTERY NUMBERS</span><h2 style="margin-top:12px">Sources & data health</h2><p>The earlier recommendation lists are the discovery source, not proof. Steam identities are rechecked against the store API; off-Steam identities come from exact creator and community project pages. Unknown dates, scores, and media stay unknown rather than being filled in.</p><div class="detail-stats"><div class="stat-box"><strong>${games.length}</strong><small>Unique records preserved</small></div><div class="stat-box"><strong>${games.length-unresolved.length}</strong><small>Verified project identities</small></div><div class="stat-box"><strong>${unresolved.length}</strong><small>Awaiting verification</small></div><div class="stat-box"><strong>${games.length-unresolved.length-noTrailer.length}</strong><small>With official embedded trailers</small></div></div><h3>How the scores work</h3><p><strong>Steam rating</strong> is the positive percentage from all-language, all-purchase-type Steam reviews. Review count is always shown. It may differ from the localized Steam store label. <strong>Recommendation</strong> is editorial fit for your requested style, not a claim of hands-on testing. Low player reception and extremely small samples cap the score. <strong>itch.io / ModDB ratings</strong> retain their native scale and count. They are never silently converted into Steam percentages. <strong>Your rating</strong> is separate and belongs only to you.</p><p>Steam's store release date may reflect the full launch rather than the first Early Access release. Upcoming games, public demos, prototypes, mods, and adjacent genres are explicitly labelled. Mod downloads can require an owned base game; the detail page shows these prerequisites. US prices are snapshots, not live offers.</p><h3>Snapshot</h3><p>Checked: ${esc(CATALOG.generatedAt||'Unknown')}<br>Dataset SHA-256: <code style="overflow-wrap:anywhere">${esc(CATALOG.build?.datasetHash||'Not available')}</code><br>${stale.length} entries retained from a prior snapshot after a refresh failure.<br>${noTrailer.length} verified entries without an embeddable official trailer.</p><div class="settings-actions"><button class="primary" data-action="refresh">Check for newer snapshot</button><a class="secondary" href="https://github.com/Herbertofury/Games/actions/workflows/refresh.yml" target="_blank" rel="noopener">Refresh official Steam facts ${icon('external')}</a><a class="secondary" href="https://github.com/Herbertofury/Games/blob/main/data/seeds.tsv" target="_blank" rel="noopener">Edit the master list ${icon('external')}</a></div>${unresolved.length?'<h3>Needs verification</h3><div class="health-list">'+unresolved.map(g=>`<div><strong>${esc(g.name)}</strong><br>${esc((g.warnings||[]).join('; '))}<br><a href="${esc(projectURL(g))}" target="_blank" rel="noopener">Inspect original, unverified project link</a></div>`).join('')+'</div>':''}<h3>Nothing is silently removed</h3><p>Unresolved recommendations stay in the catalog with no invented score or artwork. Refresh failures retain prior verified data and its original timestamp. No personal notes or favorites are sent to Steam or GitHub.</p></div>`);updateURL();}
function settings(){stopMedia();currentGame=null;openModal(`<div class="simple-modal"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2 style="margin-top:12px">Your library, your way.</h2><p>Favorites, play status, personal ratings, notes, saved views, and display preferences are stored in this browser. They do not sync between devices automatically.</p>${!storageOK?'<p class="storage-warning">Browser storage is unavailable. This session still works, but export a backup before closing it.</p>':''}<div class="settings-actions"><button class="secondary" data-action="theme">${icon('sun')}Toggle theme</button><button class="secondary" data-action="density">${icon('list')}${prefs.compact?'Comfortable':'Compact'} cards</button></div><h3>Take your library with you</h3><p>Backups preserve your personal data separately from the recommendation catalog. Import merges saved games and notes without removing your existing collection.</p><div class="settings-actions"><button class="primary" data-action="backup">${icon('download')}Export personal backup</button><button class="secondary" data-action="import">Import personal backup</button></div><h3>Keep the collection growing</h3><p>Add a game using its Steam app ID. The repository owns the master list; its refresh workflow checks Steam, updates media and ratings, and rebuilds the same catalog and wiki pages. No API key is needed.</p><div class="settings-actions"><a class="secondary" href="https://github.com/Herbertofury/Games/issues/new?template=game.yml" target="_blank" rel="noopener">Add a game ${icon('plus')}</a><a class="secondary" href="https://github.com/Herbertofury/Games/actions/workflows/refresh.yml" target="_blank" rel="noopener">Run metadata refresh ${icon('external')}</a></div><h3>Keyboard shortcuts</h3><p><kbd>/</kbd> Search &nbsp; <kbd>Esc</kbd> Close details &nbsp; <kbd>\u2190</kbd> / <kbd>\u2192</kbd> Previous / next media<br>Search supports exact phrases, exclusions such as <code>-zombie</code>, <code>tag:loot</code>, <code>score&gt;=9</code>, and <code>rating&gt;=90</code>.</p><p>Artwork and videos come from official Steam and creator/project pages. Creator videos load only when requested. No analytics, advertising, or accounts are required. The offline snapshot retains the catalog and your tools; uncached images and trailers still need an internet connection.</p></div>`);updateURL();}
async function refreshSnapshot(){toast('Checking the canonical catalog snapshot...');try{const r=await fetch('https://raw.githubusercontent.com/Herbertofury/Games/main/data/catalog.json',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.schemaVersion!==1||!Array.isArray(d.items)||!d.items.length||new Set(d.items.map(g=>g.id)).size!==d.items.length)throw Error('Snapshot failed validation');if(d.build?.datasetHash===CATALOG.build?.datasetHash){toast('You already have the latest published snapshot.');return;}CATALOG=d;setupData();options();hero();render();health();toast('Loaded the newer snapshot. Your personal library is unchanged.');}catch(e){toast('Could not refresh. Your existing snapshot is still available.');}}
const actions={menu:()=>document.body.classList.toggle('menu-open'),'focus-search':()=>{$('#library').scrollIntoView({block:'start'});$('#search').focus();},theme:()=>{prefs.theme=prefs.theme==='light'?'dark':'light';setTheme();persist();},density:()=>{prefs.compact=!prefs.compact;setTheme();persist();settings();},filters:()=>{const p=$('#filters');p.hidden=!p.hidden;$('#filter-toggle').setAttribute('aria-expanded',String(!p.hidden));},reset,close:closeModal,compare:openCompare,'clear-compare':()=>{compare.clear();render();},'hero-trailer':()=>openGame(featuredGame()?.id,true),'hero-detail':()=>openGame(featuredGame()?.id),random:()=>{const a=filtered.filter(g=>playable(g)&&recommendation(g)>=7);if(!a.length){toast('No playable recommendations match your filters.');return;}openGame(a[Math.floor(Math.random()*a.length)].id);},health,settings,refresh:refreshSnapshot,backup,import:()=>$('#import-file').click(),share:()=>copy(location.protocol==='file:'?'https://herbertofury.github.io/Games/'+location.hash:location.href),export:()=>{stopMedia();currentGame=null;openModal(`<div class="simple-modal"><h2>Take the collection with you.</h2><p>Export all ${filtered.length} games in your current filtered view. CSV includes your personal ratings, play status, and notes. JSON contains the public catalog records only.</p><div class="settings-actions"><button class="primary" data-export="csv">Download CSV</button><button class="secondary" data-export="json">Download JSON</button></div><h3>Your complete personal library</h3><p>A personal backup also includes saved views, favorites, and preferences.</p><button class="secondary" data-action="backup">Export personal backup</button></div>`);updateURL();},'save-view':()=>{stopMedia();currentGame=null;openModal('<div class="simple-modal"><h2>Save this view.</h2><p>Keep this exact search, filter combination, sort order, and display mode.</p><label for="view-name">View name</label><input id="view-name" type="text" maxlength="60" placeholder="Dark fantasy, highly rated"><button class="primary" data-action="commit-view">Save view</button></div>');$('#view-name').focus();},'commit-view':()=>{const name=$('#view-name').value.trim();if(!name){toast('Give your view a name.');return;}prefs.views.push({name,filters:{...state}});persist();renderViews();closeModal();toast('View saved.');}};
document.addEventListener('click',e=>{const h=e.target.closest('button[data-hub]');if(h){state={...defaults,view:state.view,hub:h.dataset.hub};render();document.body.classList.remove('menu-open');window.scrollTo({top:0});}const y=e.target.closest('[data-youtube]');if(y&&/^[A-Za-z0-9_-]{11}$/.test(y.dataset.youtube)){const f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+y.dataset.youtube+'?autoplay=1';f.title=(currentGame?.name||'Game')+' official trailer';f.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';f.referrerPolicy='strict-origin-when-cross-origin';f.allowFullscreen=true;f.className='trailer-frame';y.closest('.media-stage').replaceChildren(f);}});
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-action]');if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();return;}if(b.dataset.open)return openGame(b.dataset.open);if(b.dataset.trailer)return openGame(b.dataset.trailer,true);if(b.dataset.save)return toggleSave(b.dataset.save);if(b.dataset.addCompare){setCompare(b.dataset.addCompare,!compare.has(b.dataset.addCompare));toast(compare.has(b.dataset.addCompare)?'Added to comparison.':'Removed from comparison.');return;}if(b.dataset.copyGame)return copy(gameLink(b.dataset.copyGame));if(b.dataset.shelf){state={...defaults,view:state.view,shelf:b.dataset.shelf};document.body.classList.remove('menu-open');render();$('#library').scrollIntoView({block:'start',behavior:'smooth'});return;}if(b.dataset.collection){state.collection=state.collection===b.dataset.collection?'':b.dataset.collection;state.shelf='all';document.body.classList.remove('menu-open');render();$('#library').scrollIntoView({block:'start',behavior:'smooth'});return;}if(b.dataset.preset)return preset(b.dataset.preset);if(b.dataset.tag){state.tag=b.dataset.tag;render();return;}if(b.dataset.view){state.view=b.dataset.view;render();return;}if(b.dataset.sort){state.sort=b.dataset.sort;render();return;}if(b.dataset.clear){state[b.dataset.clear]=defaults[b.dataset.clear];render();return;}if(b.dataset.loadView!==undefined){state={...defaults,...prefs.views[+b.dataset.loadView].filters};render();return;}if(b.dataset.deleteView!==undefined){prefs.views.splice(+b.dataset.deleteView,1);persist();renderViews();return;}if(b.dataset.export)return exportData(b.dataset.export);if(b.dataset.mediaMode){mediaMode=b.dataset.mediaMode;mediaIndex=0;renderMedia();return;}if(b.dataset.mediaIndex!==undefined){mediaIndex=+b.dataset.mediaIndex;renderMedia();return;}if(b.dataset.mediaStep){const data=mediaMode==='trailer'?trailers(currentGame):currentGame.screenshots;mediaIndex=(mediaIndex+ +b.dataset.mediaStep+data.length)%data.length;renderMedia();}});
$('#search').addEventListener('input',e=>{state.q=e.target.value;render();});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render();});for(const k of ['hub','provider','kind','scope','hostRating','collection','tag','rating','reviews','fit','year','status','play','coop','free','trailer','verified','playable','hidden','offSteam'])$('#f-'+k).addEventListener('change',e=>{state[k]=typeof defaults[k]==='boolean'?e.target.checked:typeof defaults[k]==='number'?Number(e.target.value):e.target.value;render();});
document.addEventListener('change',e=>{if(e.target.dataset.compare)setCompare(e.target.dataset.compare,e.target.checked);if(e.target.id==='detail-status'&&currentGame){prefs.statuses[currentGame.id]=e.target.value;persist();render();}if(e.target.id==='personal-rating'&&currentGame){prefs.ratings[currentGame.id]=Number(e.target.value)||null;persist();render();}});document.addEventListener('input',e=>{if(e.target.id==='game-notes'&&currentGame){prefs.notes[currentGame.id]=e.target.value;persist();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Backup is too large');const d=JSON.parse(await f.text());if(d.schemaVersion!==1||!Array.isArray(d.favorites)||!d.notes||typeof d.notes!=='object')throw Error('Not a Games personal backup');prefs.favorites=[...new Set([...prefs.favorites,...d.favorites.filter(id=>typeof id==='string')])];for(const k of ['notes','statuses','ratings'])for(const [id,v]of Object.entries(d[k]||{})){if(!/^(?:(?:steam|pending):\d+|external:[a-z0-9-]+)$/.test(id))continue;if(k==='notes'&&typeof v==='string')prefs.notes[id]=v;if(k==='statuses'&&['','Backlog','Playing','Completed','Dropped'].includes(v))prefs.statuses[id]=v;if(k==='ratings'&&Number(v)>=1&&Number(v)<=10)prefs.ratings[id]=Number(v);}if(Array.isArray(d.views))for(const v of d.views)if(v&&typeof v.name==='string'&&v.filters&&!prefs.views.some(x=>x.name===v.name))prefs.views.push({name:v.name,filters:{...defaults,...Object.fromEntries(Object.keys(defaults).filter(k=>k in v.filters).map(k=>[k,v.filters[k]]))}});persist();renderViews();render();toast('Backup merged. Your existing games and notes were preserved.');}catch(err){toast('Import failed: '+err.message);}e.target.value='';});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(e.key==='/'&&!typing&&!$('#modal').open){e.preventDefault();actions['focus-search']();}if(e.key==='Escape')document.body.classList.remove('menu-open');if(!typing&&currentGame&&['ArrowLeft','ArrowRight'].includes(e.key)&&$('#media-area')){e.preventDefault();const data=mediaMode==='trailer'?trailers(currentGame):currentGame.screenshots;if(data.length){mediaIndex=(mediaIndex+(e.key==='ArrowRight'?1:-1)+data.length)%data.length;renderMedia();}}if(e.key==='Enter'&&e.target.id==='view-name')actions['commit-view']();});
window.addEventListener('hashchange',()=>{const id=readURL();render();if(id&&byId.has(id)&&currentGame?.id!==id)openGame(id);else if(!id&&currentGame)closeModal();});document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.style.opacity='.15';e.target.alt=e.target.alt||'Official image unavailable';}},true);
