window.GamesTest={get count(){return games.length;},get filtered(){return filtered.map(g=>g.id);},get state(){return {...state};},get personal(){return prefs;},queryMatches,recommendation};

function projectURL(g){return safeURL(g.primaryUrl||g.steamUrl);}
function ratingText(g){return g.rating!=null?g.rating+'%':g.externalRating?g.externalRating.value+' / '+g.externalRating.max:'Unrated';}
function reviewText(g){return g.steamUrl?(g.reviewCount?compact(g.reviewCount)+' Steam reviews':'No Steam review sample'):g.externalRating?g.externalRating.count+' '+g.externalRating.provider+' ratings':'Creator-verified; no aggregate score';}
function hiddenGem(g){return !!g.hiddenGem||!!(g.steamUrl&&!g.comingSoon&&g.reviewCount>=10&&g.reviewCount<=1500&&g.rating>=80);}
function sourcePanel(g){return `<section class="detail-section source-panel"><h3>Get it from the source</h3><div class="storefronts">${(g.storefronts||[{provider:'Steam',url:g.steamUrl,kind:'store'}]).filter(x=>safeURL(x.url)).map(x=>`<a class="secondary" href="${esc(safeURL(x.url))}" target="_blank" rel="noopener">${icon('external')}${esc(x.provider)} <small>${esc(x.kind==='support'?'Support / devlogs':x.kind==='demo'?'Playable demo':x.kind==='download'?'Download':x.kind==='browser'?'Play in browser':x.kind==='project'?'Project page':'Store')}</small></a>`).join('')}</div>${g.kind?`<p><strong>${esc(g.kind)}</strong>${g.genreScope?' &middot; '+esc(g.genreScope):''}</p>`:''}${g.requirements?`<div class="requirements"><strong>Before you play</strong><p>${esc(g.requirements)}</p></div>`:''}${g.updateNote?`<p><strong>Latest verified update:</strong> ${esc(g.updateNote)}</p>`:''}${(g.storefronts||[]).some(x=>x.kind==='support')?'<p class="support-note">Patreon links are creator support / development pages. Membership does not automatically include a game license or access to every build. Check the current tier before paying.</p>':''}<details><summary>Source evidence & verification</summary>${(g.sources||[]).filter(x=>safeURL(x.url)).map(x=>`<p><a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener">${esc(x.label||x.provider||'Official source')}</a>${x.lastChecked?' &middot; '+esc(x.lastChecked.slice(0,10)):''}</p>`).join('')}</details></section>`;}
function extraOptions(){for(const [k,values,label] of [['hub',[...new Set(games.flatMap(g=>g.hubs||['Roguelites']))],'All genre hubs'],['provider',[...new Set(games.flatMap(g=>(g.storefronts||[]).map(x=>x.provider)))],'All platforms'],['kind',[...new Set(games.map(g=>g.kind||'Standalone game'))],'All build types'],['scope',[...new Set(games.map(g=>g.genreScope).filter(Boolean))],'All FPS styles']])$('#f-'+k).innerHTML=`<option value="">${label}</option>`+values.sort().map(x=>`<option>${esc(x)}</option>`).join('');}
var renderedHub;
function renderHub(){if(renderedHub===state.hub)return;renderedHub=state.hub;document.body.dataset.hub=state.hub==='Boomer shooters'?'shooters':'all';$('.breadcrumb strong').textContent=state.hub||'All games';$('.intro h1').innerHTML=state.hub==='Boomer shooters'?'Make some noise<span>.</span>':state.hub==='Roguelites'?'One more run<span>.</span>':'Your next obsession<span>.</span>';$('.intro p').textContent=state.hub==='Boomer shooters'?'Big guns, secret doors, impossible speed. From the newest releases to the underground FPS scene.':state.hub==='Roguelites'?'Ridiculous builds, impossible odds, and the games you keep coming back to.':'A living home for extraordinary games. Across genres, storefronts, and the places worth digging deeper.';$('.feature-pill').innerHTML=icon('spark')+(state.hub==='Boomer shooters'?' THE NEW RELEASE SPOTLIGHT':' THE GAME THAT STARTED THIS COLLECTION');$('.feature-index strong').textContent=state.hub==='Boomer shooters'?'02 / THE BOOMER SHOOTER COLLECTION':'01 / THE ROGUELITE COLLECTION';const t=$('[data-preset="torment"]');t.querySelector('strong').textContent=state.hub==='Boomer shooters'?'Under the radar':'The Torment feeling';t.querySelector('small').textContent=state.hub==='Boomer shooters'?'Smaller audiences. Big personality.':'Dark fantasy & dangerous builds';$$('[data-hub]').forEach(n=>n.classList.toggle('active',n.dataset.hub===state.hub));hero();}
